from math import ceil
from copy import deepcopy
from typing import Literal, Iterable

from lv1_circuits import *
from gate_types import Lv1LogicalOp, LogicalOp, Lv1ObsOp

class AbstractCircuit:
    '''
    Allow direct generation of level-1 circuits. 
    '''
    def __init__(self, lv1_code: Lv1CSSCode,
                 inner_distance: int, 
                 bus_length: int,
                 external_cores: Optional[ExtCores] = None):
        self.lv1_code = lv1_code
        self.lv1_circuit = Lv1Circuit()
        self.clock_time: int = 0
        self.time_unit = 2
        self.half_time_unit = 1
        self.inner_distance = inner_distance
        self.bus_length = bus_length
        self.patch_2_lv1_qubit: dict[int, Lv1Qubit] = {}
        self.lv1_length: int = 0
        self.external_cores = external_cores
        self._lv1_circuit_init()

    @property
    def num_logical_qubits(self) -> int:
        return len(self.lv1_code.logical_qubits)

    def _lv1_circuit_init(self):
        patch_id_temp = 0
        for lv1_qubit in self.lv1_code.distinct_pos_2_qubit.values():
            assert lv1_qubit.code_patch is None
            if lv1_qubit.virtual_patch_id is not None:
                raise ValueError(f'{lv1_qubit=} is already assigned a virtual patch id '
                                 f'{lv1_qubit.virtual_patch_id=}')
            lv1_qubit.virtual_patch_id = patch_id_temp
            self.lv1_circuit.add_new_core(lv1_qubit)
            self.patch_2_lv1_qubit[lv1_qubit.patch_id] = lv1_qubit
            patch_id_temp += 1
        if self.external_cores is not None:
            for lv1_qubit in self.external_cores.pos_2_core.values():
                if lv1_qubit.core_type not in [CoreType.ZBUS, CoreType.XBUS]:
                    continue
                assert lv1_qubit.code_patch is None
                assert lv1_qubit.virtual_patch_id is None
                lv1_qubit.virtual_patch_id = patch_id_temp
                self.lv1_circuit.add_new_core(lv1_qubit, external=True)
                self.patch_2_lv1_qubit[lv1_qubit.patch_id] = lv1_qubit
                patch_id_temp += 1
            for lv1_qubit in self.external_cores.pos_2_core.values():
                if lv1_qubit.core_type != CoreType.EXTCORE:
                    continue
                assert lv1_qubit.code_patch is None
                assert lv1_qubit.virtual_patch_id is None
                lv1_qubit.virtual_patch_id = patch_id_temp
                self.lv1_circuit.add_new_core(lv1_qubit, external=True)
                self.patch_2_lv1_qubit[lv1_qubit.patch_id] = lv1_qubit
                patch_id_temp += 1
        for logical_qubit in self.lv1_code.logical_qubits:
            self.lv1_circuit.add_new_lv1_dummy_qubit(logical_qubit)
        if self.external_cores is not None:
            for external_logical_qubit in self.external_cores.external_logical_qubits:
                self.lv1_circuit.add_new_lv1_dummy_qubit(external_logical_qubit)
        self.lv1_circuit.initalize_lv1_circuit()

    def _register_anc_patch_reset(self, patch_id: int, reset_gate: Gate):
        '''
        Register a level-1 reset operation on an ancilla bus patch. 
        Support of active level-1 detecting regions generated by the bus is updated.
        A new level-1 detecting region is generated from this reset operation.  
        
        :param patch_id: 
        :type patch_id: int
        :param reset_gate: 
        :type reset_gate: Gate
        '''
        assert patch_id in self.patch_2_lv1_qubit
        bus = self.patch_2_lv1_qubit[patch_id]
        if bus.core_type not in [CoreType.XBUS, CoreType.ZBUS]:
            raise TypeError(f'{patch_id=} has type {bus.core_type}, which should be a bus')
        self.lv1_circuit.patch_2_timeline[patch_id].add_new_event(
            Lv1_Op(reset_gate, 
                   targets=tuple([Lv1ID_port(patch_id,i) 
                                    for i in range(self.bus_length)])),
            time=self.current_lv1_time
        )
        if reset_gate not in ACTIVATE_INSTRUCTIONS:
            raise TypeError(f'{reset_gate=} should be in {ACTIVATE_INSTRUCTIONS=}')
        if reset_gate in [Gate.RX, Gate.MPP_RX]:
            supp = set([(patch_id, Pauli.X)])
            reset_basis = Pauli.X
        elif reset_gate in [Gate.RZ, Gate.MPP_RZ]:
            supp = set([(patch_id, Pauli.Z)])
            reset_basis = Pauli.Z
        else:
            raise RuntimeError(f'Lv1Det auto generation failed. Reset opeartion {reset_gate} '
                               f'is not specified a specific basis.')
        new_det = Lv1Det(self.lv1_circuit.lv1Det_id_new,supp,
                         anc_patch_id=patch_id,
                         pos=bus.distinct_position
                         )
        for lv1_det_id in self.lv1_circuit\
                          .patch_2_generated_active_lv1Det_ids[patch_id]:
            lv1_det = self.lv1_circuit.lv1Det_id_2_lv1Det[lv1_det_id]
            if lv1_det.anc_patch_id != patch_id:
                continue
            lv1_det.supp_update(supp)
            if self._test_support_on_patch(lv1_det.supp, patch_id, reset_basis):
                self.lv1_circuit.add_new_lv1_det_to_patch(lv1_det, patch_id)
        self.lv1_circuit.generate_new_lv1_Det_id
        self.lv1_circuit.lv1Det_id_2_lv1Det[new_det.id] = new_det
        self.lv1_circuit.introduce_new_lv1_det_from_patch(patch_id, new_det)
        self.lv1_circuit.add_new_lv1_det_to_patch(new_det, patch_id)

    def _register_inter_cnot(self, bus_id: int, data_id: int, 
                             cnot_direction: Literal['CT','TC'],
                             port: int):
        bus = self.patch_2_lv1_qubit[bus_id]
        data_core = self.patch_2_lv1_qubit[data_id]
        if bus.core_type not in [CoreType.XBUS, CoreType.ZBUS]:
            raise TypeError(f'{bus=} has type {bus.core_type=} '
                            f'which is not an Ancilla Bus type')
        if data_core.core_type != CoreType.INTCORE:
            raise TypeError(f'{data_core=} has type {data_core.core_type=} '
                            f'which is not the Data Core type.')
        if cnot_direction == 'CT':
            lv1_op = Lv1_Op(Gate.CX, (Lv1ID_port(bus_id,port),
                                      Lv1ID_port(data_id,0)))
            bus_to_data_basis = Pauli.X
            data_to_bus_basis = Pauli.Z
        else:
            assert cnot_direction == 'TC'
            lv1_op = Lv1_Op(Gate.CX, (Lv1ID_port(data_id,0),
                                      Lv1ID_port(bus_id,port)))
            bus_to_data_basis = Pauli.Z
            data_to_bus_basis = Pauli.X
        self.lv1_circuit.patch_2_timeline[bus_id].add_new_event(
            lv1_op, self.current_lv1_time
        )
        self.lv1_circuit.patch_2_timeline[data_id].add_new_event(
            lv1_op, self.current_lv1_time
        )
        # anc det region propagates to data
        for lv1_det_id in self.lv1_circuit.patch_2_lv1Det_ids[bus_id]:
            lv1_det = self.lv1_circuit.lv1Det_id_2_lv1Det[lv1_det_id]
            supp_on_bus = self._test_support_on_patch(lv1_det.supp, bus_id, bus_to_data_basis)
            if not supp_on_bus:
                continue
            lv1_det.supp_update([(data_id, bus_to_data_basis)])
            if self._test_support_on_patch(lv1_det.supp, data_id, bus_to_data_basis):
                self.lv1_circuit.add_new_lv1_det_to_patch(lv1_det, data_id)
            else:
                self.lv1_circuit.remove_lv1_det_from_patch(lv1_det, data_id)
        # data det region propagates to anc
        for lv1_det_id in self.lv1_circuit.patch_2_lv1Det_ids[data_id]:
            lv1_det = self.lv1_circuit.lv1Det_id_2_lv1Det[lv1_det_id]
            supp_on_core = self._test_support_on_patch(lv1_det.supp, data_id, data_to_bus_basis)
            if not supp_on_core:
                continue
            lv1_det.supp_update([(bus_id, data_to_bus_basis)])
            if self._test_support_on_patch(lv1_det.supp, bus_id, data_to_bus_basis):
                self.lv1_circuit.add_new_lv1_det_to_patch(lv1_det, bus_id)
            else:
                self.lv1_circuit.remove_lv1_det_from_patch(lv1_det, bus_id)
        # data obs to anc
        for lv1_obs_id in self.lv1_circuit.patch_2_lv1Obs_ids[data_id]:
            lv1_obs = self.lv1_circuit.lv1Obs_id_2_lv1Obs[lv1_obs_id]
            supp_on_core = self._test_support_on_patch(lv1_obs.supp, data_id, data_to_bus_basis)
            if not supp_on_core:
                continue
            lv1_obs.supp_update([(bus_id, data_to_bus_basis)])
            lv1_obs.lv1_supp_update([(bus_id, data_to_bus_basis)])
        # bus obs to core
        for lv1_obs_id in self.lv1_circuit.patch_2_lv1Obs_ids[bus_id]:
            lv1_obs = self.lv1_circuit.lv1Obs_id_2_lv1Obs[lv1_obs_id]
            supp_on_bus = self._test_support_on_patch(lv1_obs.supp, bus_id, bus_to_data_basis)
            if not supp_on_bus:
                continue
            lv1_obs.supp_update([(data_id, bus_to_data_basis)])
            lv1_obs.lv1_supp_update([(data_id, bus_to_data_basis)]) 
            if self._test_support_on_patch(lv1_obs.supp, data_id, bus_to_data_basis):
                self.lv1_circuit.link_lv1_obs_to_patch(lv1_obs, data_id)
            else:
                self.lv1_circuit.unlink_lv1_obs_to_patch(lv1_obs, data_id)
        pass

    def _register_anc_meas(self, patch_id: int, meas_gate: Gate):
        assert patch_id in self.patch_2_lv1_qubit
        bus = self.patch_2_lv1_qubit[patch_id]
        if bus.core_type not in [CoreType.XBUS, CoreType.ZBUS]:
            raise TypeError(f'{patch_id=} has type {bus.core_type} '
                            f'which should be an ancilla')
        meas_op = Lv1_Op(
            meas_gate, 
            targets=tuple([Lv1ID_port(patch_id,i) 
                           for i in range(self.bus_length)])
            )
        if meas_gate in [Gate.MX, Gate.MZ]:
            meas_time = Lv1Time(self.current_lv1_time.lv1_cycle_time,
                                self.current_lv1_time.clock_time+1)
        else:
            meas_time = self.current_lv1_time
        self.lv1_circuit.patch_2_timeline[patch_id].add_new_event(
            meas_op,
            time=meas_time
        )
        if meas_gate not in DEACTIVATE_INSTRUCTIONS:
            raise TypeError(f'{meas_gate=} should be in {DEACTIVATE_INSTRUCTIONS=}')
        if meas_gate in [Gate.MX, Gate.MPP_MX]:
            meas_basis = Pauli.X
        else:
            assert meas_gate in [Gate.MZ, Gate.MPP_MZ]
            meas_basis = Pauli.Z
        det_ids_connected_to_patch = deepcopy(self.lv1_circuit.patch_2_lv1Det_ids[patch_id])
        for lv1_det_id in det_ids_connected_to_patch:
            lv1_det = self.lv1_circuit.lv1Det_id_2_lv1Det[lv1_det_id]
            supp_on_bus_wrong_basis = self._test_support_on_patch(lv1_det.supp, patch_id,
                                                    Pauli.X if meas_basis == Pauli.Z else Pauli.Z)
            if supp_on_bus_wrong_basis:
                raise ValueError(f'{lv1_det=} gets annihilated by '
                                 f'{meas_basis} basis measurement on patch {patch_id}')
            supp_on_bus = self._test_support_on_patch(lv1_det.supp, patch_id, meas_basis)
            if supp_on_bus:
                lv1_det.add_lv1_meas(meas_time, meas_op)
            lv1_det.supp_update([(patch_id, meas_basis)])
            self.lv1_circuit.remove_lv1_det_from_patch(lv1_det, patch_id)
            if len(lv1_det.supp) == 0:
                self.lv1_circuit.deactivate_lv1_det(lv1_det.id)
        obs_ids_connected_to_patch = deepcopy(self.lv1_circuit.patch_2_lv1Obs_ids[patch_id])
        for obs_id in obs_ids_connected_to_patch:
            obs = self.lv1_circuit.lv1Obs_id_2_lv1Obs[obs_id]
            is_supported = self._test_support_on_patch(obs.supp, patch_id, meas_basis)
            if is_supported:
                obs.add_lv1_meas(meas_time, meas_op)
            for target in obs.supp:
                if target[0] != patch_id:
                    continue
                if target[-1] != meas_basis:
                    raise ValueError(f'{obs=} gets annihilated by '
                        f'{meas_basis} basis measurement on patch {patch_id}')
            if is_supported:
                obs.supp_update([(patch_id, meas_basis)])
                obs.lv1_supp_update([(patch_id, meas_basis)])
                self.lv1_circuit.remove_lv1_obs_from_patch(obs, patch_id)

    def _test_support_on_patch(self, supp: Iterable[tuple[int,Pauli]], 
                               patch_id: int, basis: Pauli) -> bool:
        for pauli_op in supp:
            if pauli_op[0] == patch_id and pauli_op[1] == basis:
                return True
        return False
    
    def _handle_external_operations(self, instructions: list[CoreInstruction]):
        for instruction in instructions:
            target_qubit = self.external_cores.pos_2_core[instruction.target_pos]
            if instruction.core_operation in [CoreOp.RX, CoreOp.RZ]:
                reset_gate = Gate.RX if instruction.core_operation == CoreOp.RX else Gate.RZ
                if target_qubit.core_type in [CoreType.XBUS, CoreType.ZBUS]:
                    self._register_anc_patch_reset(target_qubit.patch_id, reset_gate)
                else:
                    raise NotImplementedError(f'External {target_qubit=} is not supported '
                                              f'for {instruction.core_operation}')
            elif instruction.core_operation == CoreOp.CX:
                if instruction.ctrl_type != CoreType.INTCORE:
                    ctrl_qubit = self.external_cores.pos_2_core[instruction.ctrl_pos]
                else:
                    ctrl_qubit = self.lv1_code.distinct_pos_2_qubit[instruction.ctrl_pos]
                if ctrl_qubit.core_type == CoreType.INTCORE:
                    assert target_qubit.core_type == CoreType.ZBUS
                    self._register_inter_cnot(target_qubit.patch_id, ctrl_qubit.patch_id, 
                                              'TC', port=instruction.target_port)
                else:
                    assert ctrl_qubit.core_type == CoreType.XBUS
                    assert target_qubit.core_type == CoreType.INTCORE
                    self._register_inter_cnot(ctrl_qubit.patch_id, target_qubit.patch_id, 
                                              'CT', port=instruction.ctrl_port)
            elif instruction.core_operation in [CoreOp.MZ, CoreOp.MX]:
                if target_qubit.core_type in [CoreType.ZBUS, CoreType.XBUS]:
                    meas_gate = Gate.MX if target_qubit.core_type == CoreType.XBUS \
                                        else Gate.MZ
                    self._register_anc_meas(target_qubit.patch_id, meas_gate)

    def _handle_external_obs_operations(self, obs_instructions: list[ObsInstruction]):
        for obs_inst in obs_instructions:
            if obs_inst.obs_operation == Lv1ObsOp.ADD:
                target_qubit = self.external_cores.pos_2_core[obs_inst.target_pos]
                internal_logical_qubits = [self.lv1_code.logical_qubits[index] 
                                            for index in obs_inst.internal_logical_qubit_ids]
                obs_ids = [lq.basis_2_obs_id[obs_inst.basis] for lq in internal_logical_qubits]
                if self.external_cores is not None:
                    external_logical_qubits = [self.external_cores.external_logical_qubits[index]
                                                for index in obs_inst.external_logical_qubit_ids]
                    for lq in external_logical_qubits:
                        obs_ids.append(lq.basis_2_obs_id[obs_inst.basis])
                new_obs = self.add_obs_from_existing_ones(obs_ids)
                if target_qubit.core_type in [CoreType.XBUS, CoreType.ZBUS]:
                    self.lv1_circuit.external_anc_add_meas_obs_id(target_qubit.patch_id, new_obs.obs_id)
                self.lv1_circuit.link_lv1_obs_to_patch(new_obs, target_qubit.patch_id)
                if obs_inst.basis == Pauli.X:
                    new_obs.supp_update([(target_qubit.patch_id, Pauli.X)])
                    new_obs.lv1_supp_update([(target_qubit.patch_id,Pauli.X)])
                else:
                    assert obs_inst.basis == Pauli.Z
                    new_obs.supp_update([(target_qubit.patch_id, Pauli.Z)])
                    new_obs.lv1_supp_update([(target_qubit.patch_id,Pauli.Z)])
            else:
                raise NotImplementedError(f'{obs_inst.obs_operation=} not implemented')
        pass

    def add_obs_from_existing_ones(self, obs_ids: list[int]) -> Lv1Obs:
        '''
        Generate a new observing region (`LV1Obs`) from existing ones.
        
        :param obs_ids: ids of existing `LV1Obs` objects
        :type obs_ids: list[int]
        '''
        new_obs = Lv1Obs(self.lv1_circuit.lv1Obs_id_new)
        self.lv1_circuit.generate_new_lv1_Obs_id()
        for obs_id in obs_ids:
            assert obs_id in self.lv1_circuit.lv1Obs_id_2_lv1Obs 
            old_obs = self.lv1_circuit.lv1Obs_id_2_lv1Obs[obs_id]
            new_obs.supp.symmetric_difference_update(old_obs.supp)
            new_obs.lv1_supp.symmetric_difference_update(old_obs.lv1_supp)
            for lv1_time, lv1_meas in old_obs.involved_lv1_meas:
                new_obs.add_lv1_meas(lv1_time, lv1_meas)
        for patch_id, _ in new_obs.lv1_supp:
            if self.lv1_circuit.patch_2_coretype[patch_id] != CoreType.OBSDUMMY:
                self.lv1_circuit.link_lv1_obs_to_patch(new_obs, patch_id)
        self.lv1_circuit.introduce_new_lv1_obs(new_obs)
        return new_obs

    def logical_se_round(self):
        clock_start = self.current_lv1_time.clock_time
        SE_group_indices = sorted(self.lv1_code
                                  .SE_group_index_2_anc_qubits.keys())
        inter_se_rounds = ceil(self.lv1_code.time_unit*self.inner_distance)
        se_start_padding_rds = ceil(self.lv1_code.se_start_padding_time*self.inner_distance)
        se_end_padding_rds = ceil(self.lv1_code.se_end_padding_time*self.inner_distance)
        for SE_group_index in SE_group_indices:
            # anc reset
            for anc in self.lv1_code.SE_group_index_2_anc_qubits[SE_group_index]:
                if anc.core_type == CoreType.XBUS:
                    reset_gate = Gate.RX
                else:
                    assert anc.core_type == CoreType.ZBUS
                    reset_gate = Gate.RZ
                self._register_anc_patch_reset(anc.patch_id, reset_gate)
            se_group_start_time = CoreInstTime(self.lv1_circuit.lv1_cycle_time,
                                               SE_group_index, 0)
            if self.external_cores is not None:
                if se_group_start_time in self.external_cores.time_2_instructions:
                    instructions = self.external_cores.time_2_instructions[se_group_start_time]
                    self._handle_external_operations(instructions)
                if se_group_start_time in self.external_cores.time_2_obs_instructions:
                    obs_instructions = self.external_cores.time_2_obs_instructions[se_group_start_time]
                    # print(se_group_start_time)
                    # print(obs_instructions)
                    self._handle_external_obs_operations(obs_instructions)
            self.clock_move_forward
            # inblock indices
            inblock_indices = self.lv1_code\
                              .SE_group_index_2_inblock_indices[SE_group_index]
            for i in range(max(inblock_indices)+1):
                if i in inblock_indices:
                    for data in self.lv1_code.data_qubits:
                        se_spacetime = data.check_SE_at_time(SE_group_index,i)
                        if se_spacetime is None:
                            continue
                        anc_patch = data.SEspacetime_2_qubit[se_spacetime]
                        if anc_patch.core_type == CoreType.XBUS:
                            ct = 'CT'
                        else:
                            assert anc_patch.core_type == CoreType.ZBUS
                            ct = 'TC'
                        self._register_inter_cnot(anc_patch.patch_id, data.patch_id,
                                                   ct, se_spacetime.port)
                    instruction_time = CoreInstTime(self.lv1_circuit.lv1_cycle_time,
                                                    SE_group_index, i)
                    if self.external_cores is not None and instruction_time != se_group_start_time:
                        if instruction_time in self.external_cores.time_2_instructions:
                            instructions = self.external_cores.time_2_instructions[instruction_time]
                            self._handle_external_operations(instructions)
                if i == 0:
                    for _ in range(se_start_padding_rds):
                        self.clock_move_forward
                elif i == max(inblock_indices):
                    for _ in range(se_end_padding_rds):
                        self.clock_move_forward
                else:
                    for clock_offset in range(inter_se_rounds):
                        instruction_time = CoreInstTime(self.lv1_circuit.lv1_cycle_time,
                                                        SE_group_index, i, clock_offset)
                        if clock_offset == 0:
                            self.clock_move_forward
                            continue
                        if self.external_cores is None:
                            self.clock_move_forward
                            continue
                        if instruction_time not in self.external_cores.time_2_instructions:
                            self.clock_move_forward
                            continue
                        instructions = self.external_cores.time_2_instructions[instruction_time]
                        self._handle_external_operations(instructions)
                        self.clock_move_forward
            # anc meas
            for anc in self.lv1_code.SE_group_index_2_anc_qubits[SE_group_index]:
                meas_gate = Gate.MX if anc.core_type == CoreType.XBUS \
                                    else Gate.MZ
                self._register_anc_meas(anc.patch_id, meas_gate)
            se_group_end_time = CoreInstTime(self.lv1_circuit.lv1_cycle_time,
                                             SE_group_index, -1)
            if self.external_cores is not None:
                if se_group_end_time in self.external_cores.time_2_instructions:
                    instructions = self.external_cores.time_2_instructions[se_group_end_time]
                    self._handle_external_operations(instructions)
            self.clock_move_forward
        self.lv1_cycle_time_move_forward
        if self.lv1_length == 0:
            self.lv1_length = int((self.current_lv1_time.clock_time - clock_start) / self.time_unit)
        pass

    def perf_reset(self):
        for bus in self.lv1_code.anc_qubits:
            assert bus.core_type in [CoreType.XBUS, CoreType.ZBUS]
            data_ids_sorted = sorted([data.patch_id for data in bus.SEspacetime_2_qubit.values()])
            reset_gate = Gate.MPP_RX if bus.core_type==CoreType.XBUS else Gate.MPP_RZ
            mpp_lv1_op = Lv1_Op(gate=reset_gate,
                                targets=tuple([Lv1ID_port(patch_id,0) for patch_id in data_ids_sorted]))
            for data_id in data_ids_sorted:
                self.lv1_circuit.patch_2_timeline[data_id].add_new_event(mpp_lv1_op, self.current_lv1_time)
            if bus.core_type == CoreType.XBUS:
                supp = set([(data_id, Pauli.X) for data_id in data_ids_sorted])
            else:
                supp = set([(data_id, Pauli.Z) for data_id in data_ids_sorted])
            new_det = Lv1Det(self.lv1_circuit.lv1Det_id_new, supp,
                         anc_patch_id=bus.patch_id,
                         pos=bus.distinct_position
                         )
            self.lv1_circuit.generate_new_lv1_Det_id
            self.lv1_circuit.lv1Det_id_2_lv1Det[new_det.id] = new_det
            self.lv1_circuit.introduce_new_lv1_det_from_patch(bus.patch_id, new_det)
            self.lv1_circuit.add_new_lv1_det_to_patch(new_det, bus.patch_id)
            new_det.add_lv1_meas(self.current_lv1_time, mpp_lv1_op)

        for logical_qubit in self.lv1_code.logical_qubits:
            lv1_dummy_qubit = self.lv1_circuit.logical_qubit_id_2_dummy_qubit[logical_qubit.id]
            lv1_obs_x_op = Lv1_Op(
                Gate.MPP_RX,
                targets=tuple(sorted([Lv1ID_port(lv1_dummy_qubit.circuit_id,0)] 
                              + [Lv1ID_port(id,0) for id in lv1_dummy_qubit.x_supp]))
            )
            supp_x = set([(lv1_dummy_qubit.circuit_id, Pauli.X)] + 
                         [(data_id, Pauli.X) for data_id in lv1_dummy_qubit.x_supp])
            lv1_obs_x = Lv1Obs(
                self.lv1_circuit.lv1Obs_id_new,
                supp=supp_x,
                meas_ids_buff=set(),
                logical_id=logical_qubit.id,
                logical_basis=Pauli.X,
                involved_lv1_meas=[(self.current_lv1_time,lv1_obs_x_op)],
                lv1_supp=supp_x
            )
            self.lv1_circuit.introduce_new_lv1_obs(lv1_obs_x)
            for qubit_pos in logical_qubit.x_supp:
                qubit = self.lv1_code.distinct_pos_2_qubit[qubit_pos]
                self.lv1_circuit.link_lv1_obs_to_patch(lv1_obs_x, qubit.patch_id)
            self.lv1_circuit.generate_new_lv1_Obs_id()
            self.lv1_circuit.patch_2_timeline[lv1_dummy_qubit.circuit_id].add_new_event(
                lv1_obs_x_op, self.current_lv1_time
            )
            lv1_obs_z_op = Lv1_Op(
                Gate.MPP_RZ,
                targets=tuple(sorted([Lv1ID_port(lv1_dummy_qubit.circuit_id,0)] 
                              + [Lv1ID_port(id,0) for id in lv1_dummy_qubit.z_supp]))
            )
            self.lv1_circuit.patch_2_timeline[lv1_dummy_qubit.circuit_id].add_new_event(
                lv1_obs_z_op, self.current_lv1_time
            )
            supp_z = set([(lv1_dummy_qubit.circuit_id, Pauli.Z)] + 
                         [(data_id, Pauli.Z) for data_id in lv1_dummy_qubit.z_supp])
            lv1_obs_z = Lv1Obs(
                self.lv1_circuit.lv1Obs_id_new,
                supp=supp_z,
                meas_ids_buff=set(),
                logical_id=logical_qubit.id,
                logical_basis=Pauli.Z,
                involved_lv1_meas=[(self.current_lv1_time,lv1_obs_z_op)],
                lv1_supp=supp_z
            )
            self.lv1_circuit.introduce_new_lv1_obs(lv1_obs_z)
            for qubit_pos in logical_qubit.z_supp:
                qubit = self.lv1_code.distinct_pos_2_qubit[qubit_pos]
                self.lv1_circuit.link_lv1_obs_to_patch(lv1_obs_z, qubit.patch_id)
            self.lv1_circuit.generate_new_lv1_Obs_id()

        self.clock_move_forward
        pass

    def perf_manual_reset(self, lv1_log_qubit_id_2_op: dict[int,Lv1LogicalOp]):
        for bus in self.lv1_code.anc_qubits:
            assert bus.core_type in [CoreType.XBUS, CoreType.ZBUS]
            data_ids_sorted = sorted([data.patch_id for data in bus.SEspacetime_2_qubit.values()])
            reset_gate = Gate.MPP_RX if bus.core_type==CoreType.XBUS else Gate.MPP_RZ
            mpp_lv1_op = Lv1_Op(gate=reset_gate,
                                targets=tuple([Lv1ID_port(patch_id,0) for patch_id in data_ids_sorted]))
            for data_id in data_ids_sorted:
                self.lv1_circuit.patch_2_timeline[data_id].add_new_event(mpp_lv1_op, self.current_lv1_time)
            if bus.core_type == CoreType.XBUS:
                supp = set([(data_id, Pauli.X) for data_id in data_ids_sorted])
            else:
                supp = set([(data_id, Pauli.Z) for data_id in data_ids_sorted])
            new_det = Lv1Det(self.lv1_circuit.lv1Det_id_new, supp,
                         anc_patch_id=bus.patch_id,
                         pos=bus.distinct_position
                         )
            self.lv1_circuit.generate_new_lv1_Det_id
            self.lv1_circuit.lv1Det_id_2_lv1Det[new_det.id] = new_det
            self.lv1_circuit.introduce_new_lv1_det_from_patch(bus.patch_id, new_det)
            self.lv1_circuit.add_new_lv1_det_to_patch(new_det, bus.patch_id)
            new_det.add_lv1_meas(self.current_lv1_time, mpp_lv1_op)

        for logical_qubit in self.lv1_code.logical_qubits:
            assert logical_qubit.id in lv1_log_qubit_id_2_op
            lv1_dummy_qubit = self.lv1_circuit.logical_qubit_id_2_dummy_qubit[logical_qubit.id]
            if lv1_log_qubit_id_2_op[logical_qubit.id] == Lv1LogicalOp.RX:
                lv1_obs_x_op = Lv1_Op(Gate.MPP_RX,
                                      targets=tuple(sorted([Lv1ID_port(id,0) for id in lv1_dummy_qubit.x_supp]))
                                     )
                supp = [(cid, Pauli.X) for cid in lv1_dummy_qubit.x_supp]
                lv1_obs_x = Lv1Obs(
                    self.lv1_circuit.lv1Obs_id_new,
                    supp=set(supp),
                    meas_ids_buff=set(),
                    logical_id=logical_qubit.id,
                    logical_basis=Pauli.X,
                    involved_lv1_meas=[(self.current_lv1_time,lv1_obs_x_op)],
                    lv1_supp=set(supp)
                )
                self.lv1_circuit.introduce_new_lv1_obs(lv1_obs_x)
                logical_qubit.basis_2_obs_id[Pauli.X] = lv1_obs_x.obs_id
                for patch_id in lv1_dummy_qubit.x_supp:
                    self.lv1_circuit.link_lv1_obs_to_patch(lv1_obs_x, patch_id)
                    self.lv1_circuit.patch_2_timeline[patch_id].add_new_event(
                                            lv1_obs_x_op, self.current_lv1_time)
                self.lv1_circuit.generate_new_lv1_Obs_id()
            elif lv1_log_qubit_id_2_op[logical_qubit.id] == Lv1LogicalOp.RZ:
                lv1_obs_z_op = Lv1_Op(Gate.MPP_RZ,
                                      targets=tuple(sorted([Lv1ID_port(id,0) for id in lv1_dummy_qubit.z_supp]))
                                     )
                supp = [(cid, Pauli.Z) for cid in lv1_dummy_qubit.z_supp]
                lv1_obs_z = Lv1Obs(
                    self.lv1_circuit.lv1Obs_id_new,
                    supp=set(supp),
                    meas_ids_buff=set(),
                    logical_id=logical_qubit.id,
                    logical_basis=Pauli.Z,
                    involved_lv1_meas=[(self.current_lv1_time,lv1_obs_z_op)],
                    lv1_supp=set(supp)
                )
                self.lv1_circuit.introduce_new_lv1_obs(lv1_obs_z)
                logical_qubit.basis_2_obs_id[Pauli.Z] = lv1_obs_z.obs_id
                for patch_id in lv1_dummy_qubit.z_supp:
                    self.lv1_circuit.link_lv1_obs_to_patch(lv1_obs_z, patch_id)
                    self.lv1_circuit.patch_2_timeline[patch_id].add_new_event(
                                            lv1_obs_z_op, self.current_lv1_time)
                self.lv1_circuit.generate_new_lv1_Obs_id()
            else:
                assert lv1_log_qubit_id_2_op[logical_qubit.id] == Lv1LogicalOp.BELL_RESET
                supp_x = [(lv1_dummy_qubit.circuit_id, Pauli.X)] \
                         + [(cid, Pauli.X) for cid in lv1_dummy_qubit.x_supp]
                lv1_obs_x_op = Lv1_Op(
                    Gate.MPP_RX,
                    targets=tuple(sorted([Lv1ID_port(lv1_dummy_qubit.circuit_id,0)] 
                                + [Lv1ID_port(id,0) for id in lv1_dummy_qubit.x_supp]))
                )
                lv1_obs_x = Lv1Obs(
                    self.lv1_circuit.lv1Obs_id_new,
                    supp=set(supp_x),
                    meas_ids_buff=set(),
                    logical_id=logical_qubit.id,
                    logical_basis=Pauli.X,
                    involved_lv1_meas=[(self.current_lv1_time,lv1_obs_x_op)],
                    lv1_supp=set(supp_x)
                )
                self.lv1_circuit.introduce_new_lv1_obs(lv1_obs_x)
                logical_qubit.basis_2_obs_id[Pauli.X] = lv1_obs_x.obs_id
                for patch_id in lv1_dummy_qubit.x_supp:
                    self.lv1_circuit.link_lv1_obs_to_patch(lv1_obs_x, patch_id)
                    self.lv1_circuit.patch_2_timeline[patch_id].add_new_event(
                                            lv1_obs_x_op, self.current_lv1_time)
                self.lv1_circuit.generate_new_lv1_Obs_id()
                self.lv1_circuit.patch_2_timeline[lv1_dummy_qubit.circuit_id].add_new_event(
                    lv1_obs_x_op, self.current_lv1_time
                )
                lv1_obs_z_op = Lv1_Op(
                    Gate.MPP_RZ,
                    targets=tuple(sorted([Lv1ID_port(lv1_dummy_qubit.circuit_id,0)] 
                                + [Lv1ID_port(id,0) for id in lv1_dummy_qubit.z_supp]))
                )
                self.lv1_circuit.patch_2_timeline[lv1_dummy_qubit.circuit_id].add_new_event(
                    lv1_obs_z_op, self.current_lv1_time
                )
                supp_z = [(lv1_dummy_qubit.circuit_id, Pauli.Z)] \
                         + [(cid, Pauli.Z) for cid in lv1_dummy_qubit.z_supp]
                lv1_obs_z = Lv1Obs(
                    self.lv1_circuit.lv1Obs_id_new,
                    supp=set(supp_z),
                    meas_ids_buff=set(),
                    logical_id=logical_qubit.id,
                    logical_basis=Pauli.Z,
                    involved_lv1_meas=[(self.current_lv1_time,lv1_obs_z_op)],
                    lv1_supp=set(supp_z)
                )
                self.lv1_circuit.introduce_new_lv1_obs(lv1_obs_z)
                logical_qubit.basis_2_obs_id[Pauli.Z] = lv1_obs_z.obs_id
                for patch_id in lv1_dummy_qubit.z_supp:
                    self.lv1_circuit.link_lv1_obs_to_patch(lv1_obs_z, patch_id)
                    self.lv1_circuit.patch_2_timeline[patch_id].add_new_event(
                                            lv1_obs_z_op, self.current_lv1_time)
                self.lv1_circuit.generate_new_lv1_Obs_id()
        self.clock_move_forward
        pass

    def perf_meas(self):
        for bus in self.lv1_code.anc_qubits:
            assert bus.core_type in [CoreType.XBUS, CoreType.ZBUS]
            data_ids_sorted = sorted([data.patch_id for data in bus.SEspacetime_2_qubit.values()])
            meas_gate = Gate.MPP_MX if bus.core_type==CoreType.XBUS else Gate.MPP_MZ
            mpp_lv1_op = Lv1_Op(gate=meas_gate,
                                targets=tuple([Lv1ID_port(patch_id,0) for patch_id in data_ids_sorted]))
            for data_id in data_ids_sorted:
                self.lv1_circuit.patch_2_timeline[data_id].add_new_event(mpp_lv1_op, self.current_lv1_time)

            if len(self.lv1_circuit.patch_2_generated_active_lv1Det_ids[bus.patch_id]) != 1:
                raise RuntimeError(f'{bus.patch_id=} has more than 1 active lv-1 dets left')
            
            lv1_det_id = list(self.lv1_circuit
                              .patch_2_generated_active_lv1Det_ids[bus.patch_id])[0]
            lv1_det = self.lv1_circuit.lv1Det_id_2_lv1Det[lv1_det_id]
            if bus.core_type == CoreType.XBUS:
                supp = set([(data_id, Pauli.X) for data_id in data_ids_sorted])
            else:
                supp = set([(data_id, Pauli.Z) for data_id in data_ids_sorted])
            if lv1_det.supp != supp:
                raise RuntimeError(f'{lv1_det.supp=} cannot be perfectly measured '
                                   f'by the following mpp {mpp_lv1_op}')
            lv1_det.supp_update(lv1_det.supp)
            lv1_det.add_lv1_meas(
                self.current_lv1_time,
                mpp_lv1_op
            )
            self.lv1_circuit.deactivate_lv1_det(lv1_det.id)
        for lv1_obs in self.lv1_circuit.lv1Obs_id_2_lv1Obs.values():
            if not lv1_obs.is_active:
                continue
            basis_collection = set([supp[-1] for supp in lv1_obs.supp])
            assert len(basis_collection) == 1
            op_basis = list(basis_collection)[0]
            assert len(lv1_obs.meas_ids_buff) == 0
            lv1_op = Lv1_Op(
                Gate.MPP_MX if op_basis == Pauli.X else Gate.MPP_MZ,
                targets=tuple(sorted([Lv1ID_port(id,0) for id, _ in lv1_obs.lv1_supp]))
            )
            for lv1_cid, basis in lv1_obs.lv1_supp: 
                self.lv1_circuit.patch_2_timeline[lv1_cid].add_new_event(lv1_op, self.current_lv1_time)
            lv1_obs.supp_update(lv1_obs.supp)
            lv1_obs.lv1_supp_update(lv1_obs.lv1_supp)
            lv1_obs.add_lv1_meas(self.current_lv1_time, lv1_op)

    def perf_meas_deprecated(self):
        for bus in self.lv1_code.anc_qubits:
            assert bus.core_type in [CoreType.XBUS, CoreType.ZBUS]
            data_ids_sorted = sorted([data.patch_id for data in bus.SEspacetime_2_qubit.values()])
            meas_gate = Gate.MPP_MX if bus.core_type==CoreType.XBUS else Gate.MPP_MZ
            mpp_lv1_op = Lv1_Op(gate=meas_gate,
                                targets=tuple([Lv1ID_port(patch_id,0) for patch_id in data_ids_sorted]))
            for data_id in data_ids_sorted:
                self.lv1_circuit.patch_2_timeline[data_id].add_new_event(mpp_lv1_op, self.current_lv1_time)

            if len(self.lv1_circuit.patch_2_generated_active_lv1Det_ids[bus.patch_id]) != 1:
                raise RuntimeError(f'{bus.patch_id=} has more than 1 active lv-1 dets left')
            
            lv1_det_id = list(self.lv1_circuit
                              .patch_2_generated_active_lv1Det_ids[bus.patch_id])[0]
            lv1_det = self.lv1_circuit.lv1Det_id_2_lv1Det[lv1_det_id]
            if bus.core_type == CoreType.XBUS:
                supp = set([(data_id, Pauli.X) for data_id in data_ids_sorted])
            else:
                supp = set([(data_id, Pauli.Z) for data_id in data_ids_sorted])
            if lv1_det.supp != supp:
                raise RuntimeError(f'{lv1_det.supp=} cannot be perfectly measured '
                                   f'by the following mpp {mpp_lv1_op}')
            lv1_det.supp_update(lv1_det.supp)
            lv1_det.add_lv1_meas(
                self.current_lv1_time,
                mpp_lv1_op
            )
            self.lv1_circuit.deactivate_lv1_det(lv1_det.id)
        for lv1_obs in self.lv1_circuit.lv1Obs_id_2_lv1Obs.values():
            assert lv1_obs.logical_id is not None
            if not lv1_obs.is_active:
                continue
            assert len(lv1_obs.meas_ids_buff) == 0
            obs_qubit = self.lv1_circuit.obs_id_2_obs_qubit[lv1_obs.logical_id]
            if lv1_obs.logical_basis == Pauli.X:
                lv1_obs_x_mpp = Lv1_Op(
                    Gate.MPP_MX,
                    targets=tuple(sorted([Lv1ID_port(pauli_op[0],0) for pauli_op in lv1_obs.supp]))
                )
                self.lv1_circuit.patch_2_timeline[obs_qubit.circuit_id].add_new_event(
                    lv1_obs_x_mpp, self.current_lv1_time
                )
                lv1_obs.add_lv1_meas(self.current_lv1_time, lv1_obs_x_mpp)
            else:
                assert lv1_obs.logical_basis == Pauli.Z
                lv1_obs_z_mpp = Lv1_Op(
                    Gate.MPP_MZ,
                    targets=tuple(sorted([Lv1ID_port(pauli_op[0],0) for pauli_op in lv1_obs.supp]))
                )
                self.lv1_circuit.patch_2_timeline[obs_qubit.circuit_id].add_new_event(
                    lv1_obs_z_mpp, self.current_lv1_time
                )
                lv1_obs.add_lv1_meas(self.current_lv1_time, lv1_obs_z_mpp)

    @property
    def clock_move_forward(self):
        self.clock_time += self.time_unit

    @property
    def lv1_cycle_time_move_forward(self):
        self.lv1_circuit.lv1_cycle_time += 1
    
    @property
    def current_lv1_time(self):
        return Lv1Time(self.lv1_circuit.lv1_cycle_time, self.clock_time)